/**
 * Inline code, such as a token name, flag or path (`design/components/code.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/code.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/code.module.css'

export interface CodeProps {
  children: JSX.Element
}

/** Inline code, such as a token name, flag or path. */
export default function Code(given: CodeProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <code class={styles.code} data-member="code">
        {props.children}
      </code>
    )
  })
}
